INSERT INTO challenges (guild_id, source, kind, difficulty, lang, code_lang, title, question, code, choices, answer, hint, explanation, topic, test_set, time_limit, solution, status, created_by, created_at) VALUES (NULL, 'seed', 'output', 'medium', 'fr', 'php', 'Mémoire statique', 'Qu''affiche ce code ?', 'function visit() {
    static $count = 0;
    $count++;
    return $count;
}
class Counter {
    public static int $made = 0;
    public function __construct() { self::$made++; }
}
visit(); visit();
new Counter(); new Counter(); $c = new Counter();
echo visit(), " ", Counter::$made, " ", $c::$made;', NULL, '3 3 3', 'Une variable `static` dans une fonction garde sa valeur entre les appels. Une propriété statique appartient à la classe, pas à chaque objet.', 'visit() a été appelée deux fois, le troisième appel renvoie donc 3. Trois objets ont été créés, chacun incrémente le compteur de la classe : 3, la même valeur vue par $c::$made.', 'static', NULL, NULL, NULL, 'active', 'seed', 1791475200);
INSERT INTO challenges (guild_id, source, kind, difficulty, lang, code_lang, title, question, code, choices, answer, hint, explanation, topic, test_set, time_limit, solution, status, created_by, created_at) VALUES (NULL, 'seed', 'mcq', 'medium', 'en', 'php', 'switch vs match', 'Which statement about PHP 8''s `match` is true?', NULL, '["`match` compares with `==`, like `switch`", "`match` falls through to the next arm without `break`", "`match` returns `null` when no arm matches", "`match` compares with `===` and throws an `UnhandledMatchError` when no arm matches"]', 'D', '`switch ("1") { case 1: … }` matches. Does `match` behave the same?', 'match uses strict comparison (===), never falls through, is an expression that returns a value, and throws UnhandledMatchError when nothing matches. switch uses loose ==.', 'match', NULL, NULL, NULL, 'active', 'seed', 1791475200);
INSERT INTO challenges (guild_id, source, kind, difficulty, lang, code_lang, title, question, code, choices, answer, hint, explanation, topic, test_set, time_limit, solution, status, created_by, created_at) VALUES (NULL, 'seed', 'mcq', 'medium', 'fr', 'php', 'switch ou match', 'Quelle affirmation sur le `match` de PHP 8 est vraie ?', NULL, '["`match` compare avec `==`, comme `switch`", "`match` enchaîne sur la branche suivante sans `break`", "`match` renvoie `null` si aucune branche ne correspond", "`match` compare avec `===` et lève une `UnhandledMatchError` si aucune branche ne correspond"]', 'D', '`switch ("1") { case 1: … }` correspond. `match` se comporte-t-il pareil ?', 'match compare strictement (===), n''enchaîne jamais sur la branche suivante, est une expression qui renvoie une valeur et lève UnhandledMatchError si rien ne correspond. switch utilise la comparaison souple ==.', 'match', NULL, NULL, NULL, 'active', 'seed', 1791475200);
INSERT INTO challenges (guild_id, source, kind, difficulty, lang, code_lang, title, question, code, choices, answer, hint, explanation, topic, test_set, time_limit, solution, status, created_by, created_at) VALUES (NULL, 'seed', 'mcq', 'medium', 'en', 'php', 'SQL injection', '`$pdo->query("SELECT * FROM users WHERE name = ''$name''")` is vulnerable to SQL injection. What is the right fix?', NULL, '["Use prepared statements with bound parameters (PDO `prepare` + `execute`)", "Escape quotes with `addslashes()`", "Use `htmlspecialchars()` on the input", "Check that the input is not empty"]', 'A', 'The problem is mixing data and SQL code in one string.', 'Prepared statements send the SQL and the data separately, so the data can never be read as SQL. addslashes misses cases (encodings, numeric contexts), htmlspecialchars is for HTML output, not SQL.', 'security', NULL, NULL, NULL, 'active', 'seed', 1791475200);
INSERT INTO challenges (guild_id, source, kind, difficulty, lang, code_lang, title, question, code, choices, answer, hint, explanation, topic, test_set, time_limit, solution, status, created_by, created_at) VALUES (NULL, 'seed', 'mcq', 'medium', 'fr', 'php', 'Injection SQL', '`$pdo->query("SELECT * FROM users WHERE name = ''$name''")` est vulnérable à l''injection SQL. Quelle est la bonne correction ?', NULL, '["Utiliser des requêtes préparées avec paramètres liés (PDO `prepare` + `execute`)", "Échapper les apostrophes avec `addslashes()`", "Appliquer `htmlspecialchars()` à l''entrée", "Vérifier que l''entrée n''est pas vide"]', 'A', 'Le problème est de mélanger données et code SQL dans une même chaîne.', 'Les requêtes préparées envoient le SQL et les données séparément : les données ne peuvent jamais être lues comme du SQL. addslashes oublie des cas (encodages, contextes numériques), htmlspecialchars sert à l''affichage HTML, pas au SQL.', 'security', NULL, NULL, NULL, 'active', 'seed', 1791475200);
INSERT INTO challenges (guild_id, source, kind, difficulty, lang, code_lang, title, question, code, choices, answer, hint, explanation, topic, test_set, time_limit, solution, status, created_by, created_at) VALUES (NULL, 'seed', 'complexity', 'medium', 'en', 'php', 'in_array in a loop', 'Worst case (all values different), with n = count($items), what is the complexity?', 'function dedupe(array $items): array {
    $out = [];
    foreach ($items as $x) {
        if (!in_array($x, $out, true)) {
            $out[] = $x;
        }
    }
    return $out;
}', '["O(n)", "O(n log n)", "O(n²)", "O(2ⁿ)"]', 'C', 'in_array scans the whole array it searches.', 'When every value is new, $out grows to n and each in_array scans it: 0 + 1 + … + (n-1) ≈ n²/2: O(n²). Using the values as keys (`isset($seen[$x])`) makes it O(n).', 'arrays', NULL, NULL, NULL, 'active', 'seed', 1791475200);
INSERT INTO challenges (guild_id, source, kind, difficulty, lang, code_lang, title, question, code, choices, answer, hint, explanation, topic, test_set, time_limit, solution, status, created_by, created_at) VALUES (NULL, 'seed', 'complexity', 'medium', 'fr', 'php', 'in_array dans une boucle', 'Dans le pire cas (toutes les valeurs différentes), avec n = count($items), quelle est la complexité ?', 'function dedupe(array $items): array {
    $out = [];
    foreach ($items as $x) {
        if (!in_array($x, $out, true)) {
            $out[] = $x;
        }
    }
    return $out;
}', '["O(n)", "O(n log n)", "O(n²)", "O(2ⁿ)"]', 'C', 'in_array parcourt tout le tableau où il cherche.', 'Si chaque valeur est nouvelle, $out atteint n éléments et chaque in_array le parcourt : 0 + 1 + … + (n-1) ≈ n²/2 : O(n²). Utiliser les valeurs comme clés (`isset($seen[$x])`) donne O(n).', 'arrays', NULL, NULL, NULL, 'active', 'seed', 1791475200);
INSERT INTO challenges (guild_id, source, kind, difficulty, lang, code_lang, title, question, code, choices, answer, hint, explanation, topic, test_set, time_limit, solution, status, created_by, created_at) VALUES (NULL, 'seed', 'complexity', 'medium', 'en', 'php', 'Concatenation cost', 'What is the time complexity of `reverseWords`, with n = strlen($s)?', 'function reverseWords(string $s): string {
    // s has n characters
    $words = explode(" ", $s);
    $result = "";
    for ($i = count($words) - 1; $i >= 0; $i--) {
        $result = $result . $words[$i] . " ";
    }
    return rtrim($result);
}', '["O(n²) because of the string concatenation", "O(n): PHP appends to $result in place, so each word is copied once", "O(n log n)", "O(1)"]', 'B', '`$result = $result . $x` where $result is not shared with anything else.', 'explode is O(n). PHP strings are reference-counted: when `$result . $x` is assigned back to $result and nothing else shares it, PHP extends the buffer in place (amortized), so the total work is O(n). In languages with immutable strings and no such optimization, this pattern would be O(n²).', 'strings', NULL, NULL, NULL, 'active', 'seed', 1791475200);
INSERT INTO challenges (guild_id, source, kind, difficulty, lang, code_lang, title, question, code, choices, answer, hint, explanation, topic, test_set, time_limit, solution, status, created_by, created_at) VALUES (NULL, 'seed', 'complexity', 'medium', 'fr', 'php', 'Coût de la concaténation', 'Quelle est la complexité de `reverseWords`, avec n = strlen($s) ?', 'function reverseWords(string $s): string {
    // s has n characters
    $words = explode(" ", $s);
    $result = "";
    for ($i = count($words) - 1; $i >= 0; $i--) {
        $result = $result . $words[$i] . " ";
    }
    return rtrim($result);
}', '["O(n²) à cause de la concaténation", "O(n) : PHP ajoute à $result sur place, chaque mot est copié une fois", "O(n log n)", "O(1)"]', 'B', '`$result = $result . $x` où $result n''est partagé avec rien d''autre.', 'explode est en O(n). Les chaînes PHP ont un compteur de références : quand `$result . $x` est réaffecté à $result non partagé, PHP agrandit le tampon sur place (amorti), donc le travail total est O(n). Dans un langage aux chaînes immuables sans cette optimisation, ce motif serait O(n²).', 'strings', NULL, NULL, NULL, 'active', 'seed', 1791475200);
INSERT INTO challenges (guild_id, source, kind, difficulty, lang, code_lang, title, question, code, choices, answer, hint, explanation, topic, test_set, time_limit, solution, status, created_by, created_at) VALUES (NULL, 'seed', 'bug', 'medium', 'en', 'php', 'Comparator contract', 'This sorts by age today, but PHP 8 shows a deprecation warning and it may break. What is wrong?', '$people = [["name" => "Ana", "age" => 30], ["name" => "Bo", "age" => 25], ["name" => "Cy", "age" => 35]];
usort($people, function ($a, $b) {
    return $a["age"] > $b["age"];
});
echo implode(",", array_column($people, "name"));', '["usort sorts in descending order", "array_column can''t read nested arrays", "The callback must be `static`", "The comparator returns a bool; it must return a negative, zero or positive integer: use `$a[\"age\"] <=> $b[\"age\"]`"]', 'D', 'What should a comparison function return when $a < $b?', 'usort expects an int < 0, 0 or > 0. A boolean can''t say "less than" (false means equal), which PHP 8 deprecates and some algorithms mis-sort. The spaceship operator <=> returns exactly -1, 0 or 1.', 'sorting', NULL, NULL, NULL, 'active', 'seed', 1791475200);
INSERT INTO challenges (guild_id, source, kind, difficulty, lang, code_lang, title, question, code, choices, answer, hint, explanation, topic, test_set, time_limit, solution, status, created_by, created_at) VALUES (NULL, 'seed', 'bug', 'medium', 'fr', 'php', 'Contrat du comparateur', 'Ce tri marche aujourd''hui, mais PHP 8 affiche un avertissement de dépréciation et il peut casser. Qu''est-ce qui ne va pas ?', '$people = [["name" => "Ana", "age" => 30], ["name" => "Bo", "age" => 25], ["name" => "Cy", "age" => 35]];
usort($people, function ($a, $b) {
    return $a["age"] > $b["age"];
});
echo implode(",", array_column($people, "name"));', '["usort trie par ordre décroissant", "array_column ne sait pas lire des tableaux imbriqués", "La fonction de rappel doit être `static`", "Le comparateur renvoie un booléen ; il doit renvoyer un entier négatif, nul ou positif : utilise `$a[\"age\"] <=> $b[\"age\"]`"]', 'D', 'Que doit renvoyer une fonction de comparaison quand $a < $b ?', 'usort attend un entier < 0, 0 ou > 0. Un booléen ne peut pas dire « plus petit » (false veut dire égal), ce que PHP 8 déprécie et que certains algorithmes trient mal. L''opérateur <=> renvoie exactement -1, 0 ou 1.', 'sorting', NULL, NULL, NULL, 'active', 'seed', 1791475200);
INSERT INTO challenges (guild_id, source, kind, difficulty, lang, code_lang, title, question, code, choices, answer, hint, explanation, topic, test_set, time_limit, solution, status, created_by, created_at) VALUES (NULL, 'seed', 'bug', 'medium', 'en', 'php', 'Reading input', 'With the input `3` then `10 20 30`, this prints "not ok". Why?', '// input: "3\n10 20 30\n"
$n = fgets(STDIN);
$nums = explode(" ", fgets(STDIN));
$last = $nums[$n - 1];
echo $last === "30" ? "ok" : "not ok";', '["fgets reads the whole input at once", "`$n - 1` fails because $n is a string", "fgets keeps the end-of-line `\\n`, so the last piece is \"30\\n\", not \"30\": use `trim()`", "explode needs a regex"]', 'C', 'What exactly does fgets return for the line `10 20 30`?', 'fgets returns the line WITH its newline, so the last word is "30\n". ("3\n" - 1 still works because PHP reads the leading number.) Use `trim(fgets(STDIN))` before exploding, and `intval` for numbers.', 'input', NULL, NULL, NULL, 'active', 'seed', 1791475200);
INSERT INTO challenges (guild_id, source, kind, difficulty, lang, code_lang, title, question, code, choices, answer, hint, explanation, topic, test_set, time_limit, solution, status, created_by, created_at) VALUES (NULL, 'seed', 'bug', 'medium', 'fr', 'php', 'Lire l''entrée', 'Avec l''entrée `3` puis `10 20 30`, ceci affiche « not ok ». Pourquoi ?', '// input: "3\n10 20 30\n"
$n = fgets(STDIN);
$nums = explode(" ", fgets(STDIN));
$last = $nums[$n - 1];
echo $last === "30" ? "ok" : "not ok";', '["fgets lit toute l''entrée d''un coup", "`$n - 1` échoue car $n est une chaîne", "fgets garde le saut de ligne `\\n`, donc le dernier morceau est \"30\\n\", pas \"30\" : utilise `trim()`", "explode a besoin d''une regex"]', 'C', 'Que renvoie exactement fgets pour la ligne `10 20 30` ?', 'fgets renvoie la ligne AVEC son saut de ligne, donc le dernier mot est "30\n". ("3\n" - 1 fonctionne quand même, PHP lit le nombre du début.) Utilise `trim(fgets(STDIN))` avant explode, et `intval` pour les nombres.', 'input', NULL, NULL, NULL, 'active', 'seed', 1791475200);
INSERT INTO challenges (guild_id, source, kind, difficulty, lang, code_lang, title, question, code, choices, answer, hint, explanation, topic, test_set, time_limit, solution, status, created_by, created_at) VALUES (NULL, 'seed', 'output', 'hard', 'en', 'php', 'References inside arrays', 'What does this code print?', '$a = ["x" => [1, 2]];
$ref = &$a["x"];
$b = $a;
$b["x"][] = 3;
$c = $a;
unset($ref);
$c["x"][] = 4;
echo count($a["x"]), count($b["x"]), count($c["x"]);', NULL, '444', 'When an array element is a reference, copying the array copies the reference, not the value.', '$a["x"] became a reference when $ref = &$a["x"] was taken. Copying an array copies that reference, not the value, so $b and $c share the same slot as $a. unset($ref) only removes the name $ref; the slot is still a reference shared by the three arrays. Every push lands in the same list [1, 2, 3, 4], so all three counts are 4. Avoid references inside arrays, or unset them before copying.', 'copy-on-write', NULL, NULL, NULL, 'active', 'seed', 1791475200);
INSERT INTO challenges (guild_id, source, kind, difficulty, lang, code_lang, title, question, code, choices, answer, hint, explanation, topic, test_set, time_limit, solution, status, created_by, created_at) VALUES (NULL, 'seed', 'output', 'hard', 'fr', 'php', 'Références dans les tableaux', 'Qu''affiche ce code ?', '$a = ["x" => [1, 2]];
$ref = &$a["x"];
$b = $a;
$b["x"][] = 3;
$c = $a;
unset($ref);
$c["x"][] = 4;
echo count($a["x"]), count($b["x"]), count($c["x"]);', NULL, '444', 'Quand un élément de tableau est une référence, copier le tableau copie la référence, pas la valeur.', '$a["x"] est devenu une référence quand $ref = &$a["x"] a été pris. Copier un tableau copie cette référence, pas la valeur : $b et $c partagent la même case que $a. unset($ref) ne retire que le nom $ref ; la case reste une référence partagée par les trois tableaux. Chaque ajout va dans la même liste [1, 2, 3, 4], donc les trois comptes valent 4. Évite les références dans les tableaux, ou supprime-les avant de copier.', 'copy-on-write', NULL, NULL, NULL, 'active', 'seed', 1791475200);
INSERT INTO challenges (guild_id, source, kind, difficulty, lang, code_lang, title, question, code, choices, answer, hint, explanation, topic, test_set, time_limit, solution, status, created_by, created_at) VALUES (NULL, 'seed', 'output', 'hard', 'en', 'php', 'Incrementing strings', 'What does this code print?', '$s = "Az";
$s++;
$t = "a9";
$t++;
$z = "Zz";
$z++;
echo $s, " ", $t, " ", $z, " ", "abc"[-1], " ", str_repeat("ab", 3)[4];', NULL, 'Ba b0 AAa c a', '`++` on a letter string works like an odometer: z rolls over to a and carries to the left.', '"Az"++: z → a with a carry, A → B: "Ba". "a9"++: 9 → 0 carry, a → b: "b0". "Zz"++: both roll over and a new letter is added on the left: "AAa". "abc"[-1] is "c". "ababab"[4] is "a".', 'strings', NULL, NULL, NULL, 'active', 'seed', 1791475200);
INSERT INTO challenges (guild_id, source, kind, difficulty, lang, code_lang, title, question, code, choices, answer, hint, explanation, topic, test_set, time_limit, solution, status, created_by, created_at) VALUES (NULL, 'seed', 'output', 'hard', 'fr', 'php', 'Incrémenter des chaînes', 'Qu''affiche ce code ?', '$s = "Az";
$s++;
$t = "a9";
$t++;
$z = "Zz";
$z++;
echo $s, " ", $t, " ", $z, " ", "abc"[-1], " ", str_repeat("ab", 3)[4];', NULL, 'Ba b0 AAa c a', '`++` sur une chaîne de lettres fonctionne comme un compteur kilométrique : z repasse à a avec une retenue vers la gauche.', '"Az"++ : z → a avec retenue, A → B : "Ba". "a9"++ : 9 → 0 retenue, a → b : "b0". "Zz"++ : les deux repassent et une lettre est ajoutée à gauche : "AAa". "abc"[-1] vaut "c". "ababab"[4] vaut "a".', 'strings', NULL, NULL, NULL, 'active', 'seed', 1791475200);
INSERT INTO challenges (guild_id, source, kind, difficulty, lang, code_lang, title, question, code, choices, answer, hint, explanation, topic, test_set, time_limit, solution, status, created_by, created_at) VALUES (NULL, 'seed', 'output', 'hard', 'en', 'php', 'send() to a generator', 'What does this code print?', 'function gen() {
    $x = yield 1;
    echo "[got $x]";
    $y = yield 2;
    echo "[got $y]";
    return $x + $y;
}
$g = gen();
echo $g->current();
echo $g->send(10);
echo $g->send(5);
echo "|", $g->getReturn();', NULL, '1[got 10]2[got 5]|15', 'current() runs until the first yield. send(v) resumes the generator with v as the result of the paused yield, then runs to the next yield.', 'current() prints 1. send(10): $x = 10, it echoes [got 10] and stops at yield 2, which send returns: 2. send(5): $y = 5, echoes [got 5], reaches return: send returns null (prints nothing). getReturn() is 15.', 'generators', NULL, NULL, NULL, 'active', 'seed', 1791475200);
INSERT INTO challenges (guild_id, source, kind, difficulty, lang, code_lang, title, question, code, choices, answer, hint, explanation, topic, test_set, time_limit, solution, status, created_by, created_at) VALUES (NULL, 'seed', 'output', 'hard', 'fr', 'php', 'send() à un générateur', 'Qu''affiche ce code ?', 'function gen() {
    $x = yield 1;
    echo "[got $x]";
    $y = yield 2;
    echo "[got $y]";
    return $x + $y;
}
$g = gen();
echo $g->current();
echo $g->send(10);
echo $g->send(5);
echo "|", $g->getReturn();', NULL, '1[got 10]2[got 5]|15', 'current() s''exécute jusqu''au premier yield. send(v) relance le générateur avec v comme résultat du yield en pause, puis va jusqu''au yield suivant.', 'current() affiche 1. send(10) : $x = 10, affiche [got 10] et s''arrête au yield 2, que send renvoie : 2. send(5) : $y = 5, affiche [got 5], atteint le return : send renvoie null (rien). getReturn() vaut 15.', 'generators', NULL, NULL, NULL, 'active', 'seed', 1791475200);
INSERT INTO challenges (guild_id, source, kind, difficulty, lang, code_lang, title, question, code, choices, answer, hint, explanation, topic, test_set, time_limit, solution, status, created_by, created_at) VALUES (NULL, 'seed', 'output', 'hard', 'en', 'php', 'Beyond integers', 'What does this code print? (5 values)', '$big = PHP_INT_MAX;
var_dump($big + 1 == $big + 2, is_float($big + 1), 0.1 + 0.7 == 0.8, (int) ((0.1 + 0.7) * 10), intdiv(PHP_INT_MIN, -1 + 2));', NULL, 'bool(true)
bool(true)
bool(false)
int(7)
int(-9223372036854775808)', 'Integers overflow into floats. 0.1 + 0.7 is not exactly 0.8 in binary.', 'PHP_INT_MAX + 1 becomes a float, and floats near 9.2e18 can''t tell +1 from +2: true, and it is a float: true. 0.1 + 0.7 is 0.7999999999999999: false, and × 10 then truncated gives 7. intdiv(PHP_INT_MIN, 1) is PHP_INT_MIN.', 'numbers', NULL, NULL, NULL, 'active', 'seed', 1791475200);
INSERT INTO challenges (guild_id, source, kind, difficulty, lang, code_lang, title, question, code, choices, answer, hint, explanation, topic, test_set, time_limit, solution, status, created_by, created_at) VALUES (NULL, 'seed', 'output', 'hard', 'fr', 'php', 'Au-delà des entiers', 'Qu''affiche ce code ? (5 valeurs)', '$big = PHP_INT_MAX;
var_dump($big + 1 == $big + 2, is_float($big + 1), 0.1 + 0.7 == 0.8, (int) ((0.1 + 0.7) * 10), intdiv(PHP_INT_MIN, -1 + 2));', NULL, 'bool(true)
bool(true)
bool(false)
int(7)
int(-9223372036854775808)', 'Les entiers débordent en flottants. 0.1 + 0.7 ne vaut pas exactement 0.8 en binaire.', 'PHP_INT_MAX + 1 devient un flottant, et vers 9.2e18 les flottants ne distinguent pas +1 de +2 : true, et c''est un float : true. 0.1 + 0.7 vaut 0.7999999999999999 : false, et × 10 puis tronqué donne 7. intdiv(PHP_INT_MIN, 1) vaut PHP_INT_MIN.', 'numbers', NULL, NULL, NULL, 'active', 'seed', 1791475200);
INSERT INTO challenges (guild_id, source, kind, difficulty, lang, code_lang, title, question, code, choices, answer, hint, explanation, topic, test_set, time_limit, solution, status, created_by, created_at) VALUES (NULL, 'seed', 'mcq', 'hard', 'en', 'php', 'self or static?', 'In a method of class A called as `B::create()` (B extends A), which statement is true?', NULL, '["`static::` and `self::` always refer to the same class", "`self::` refers to the class where the method is written; `static::` refers to the class that was actually called (late static binding)", "`static::` can only be used for static properties", "`parent::` refers to the object''s own class"]', 'B', 'Think about factory methods like `return new static();` in a parent class.', 'self:: is resolved where the code is written (A). static:: is resolved at runtime to the called class (B): that''s late static binding, which lets a parent factory create instances of the child class.', 'OOP', NULL, NULL, NULL, 'active', 'seed', 1791475200);
INSERT INTO challenges (guild_id, source, kind, difficulty, lang, code_lang, title, question, code, choices, answer, hint, explanation, topic, test_set, time_limit, solution, status, created_by, created_at) VALUES (NULL, 'seed', 'mcq', 'hard', 'fr', 'php', 'self ou static ?', 'Dans une méthode de la classe A appelée par `B::create()` (B extends A), quelle affirmation est vraie ?', NULL, '["`static::` et `self::` désignent toujours la même classe", "`self::` désigne la classe où la méthode est écrite ; `static::` la classe réellement appelée (liaison statique tardive)", "`static::` ne sert qu''aux propriétés statiques", "`parent::` désigne la classe de l''objet lui-même"]', 'B', 'Pense aux méthodes fabriques comme `return new static();` dans une classe parente.', 'self:: est résolu là où le code est écrit (A). static:: est résolu à l''exécution vers la classe appelée (B) : c''est la liaison statique tardive, qui permet à une fabrique du parent de créer des instances de la classe enfant.', 'OOP', NULL, NULL, NULL, 'active', 'seed', 1791475200);
INSERT INTO challenges (guild_id, source, kind, difficulty, lang, code_lang, title, question, code, choices, answer, hint, explanation, topic, test_set, time_limit, solution, status, created_by, created_at) VALUES (NULL, 'seed', 'mcq', 'hard', 'en', 'php', 'Login done right', 'Which is the correct way to store and check user passwords in PHP?', NULL, '["Store the password in `$_SESSION` to avoid asking again", "Compare `md5($password)` with the stored hash", "Hash with `sha1` and a fixed salt for all users", "Store `password_hash($password, PASSWORD_DEFAULT)` and check with `password_verify`, then call `session_regenerate_id(true)` after login"]', 'D', 'Fast hashes (md5, sha1) are easy to brute-force. Sessions can be hijacked if the id doesn''t change after login.', 'password_hash uses a slow algorithm (bcrypt/argon2) with a random salt per password; password_verify checks it in constant time. Regenerating the session id after login prevents session fixation. md5/sha1 are far too fast, and a password must never be stored in the session.', 'sessions & security', NULL, NULL, NULL, 'active', 'seed', 1791475200);
INSERT INTO challenges (guild_id, source, kind, difficulty, lang, code_lang, title, question, code, choices, answer, hint, explanation, topic, test_set, time_limit, solution, status, created_by, created_at) VALUES (NULL, 'seed', 'mcq', 'hard', 'fr', 'php', 'Connexion bien faite', 'Quelle est la bonne façon de stocker et vérifier les mots de passe en PHP ?', NULL, '["Mettre le mot de passe dans `$_SESSION` pour ne plus le redemander", "Comparer `md5($password)` au hachage stocké", "Hacher avec `sha1` et un sel fixe pour tous", "Stocker `password_hash($password, PASSWORD_DEFAULT)`, vérifier avec `password_verify`, puis appeler `session_regenerate_id(true)` après la connexion"]', 'D', 'Les hachages rapides (md5, sha1) se cassent facilement par force brute. Une session peut être volée si l''identifiant ne change pas après la connexion.', 'password_hash utilise un algorithme lent (bcrypt/argon2) avec un sel aléatoire par mot de passe ; password_verify le vérifie en temps constant. Régénérer l''identifiant de session après la connexion empêche la fixation de session. md5/sha1 sont bien trop rapides, et un mot de passe ne doit jamais être mis en session.', 'sessions & security', NULL, NULL, NULL, 'active', 'seed', 1791475200);
INSERT INTO challenges (guild_id, source, kind, difficulty, lang, code_lang, title, question, code, choices, answer, hint, explanation, topic, test_set, time_limit, solution, status, created_by, created_at) VALUES (NULL, 'seed', 'complexity', 'hard', 'en', 'php', 'Shifting cost', 'What is the time complexity of `process`?', 'function process(array $queue): int {
    // $queue has n integers
    $sum = 0;
    while (count($queue) > 0) {
        $x = array_shift($queue);     // take the first element
        $sum += $x;
    }
    return $sum;
}', '["O(n²): array_shift re-indexes the whole array every time", "O(n): count() and array_shift are O(1)", "O(n log n)", "O(1)"]', 'A', 'After array_shift, the first element has key 0 again. What did PHP have to do to the others?', 'array_shift removes the first element and renumbers every remaining integer key, which is O(n) each time: n + (n-1) + … = O(n²). count() is O(1). Use an index pointer, array_reverse + array_pop, or SplQueue for O(n).', 'arrays', NULL, NULL, NULL, 'active', 'seed', 1791475200);
INSERT INTO challenges (guild_id, source, kind, difficulty, lang, code_lang, title, question, code, choices, answer, hint, explanation, topic, test_set, time_limit, solution, status, created_by, created_at) VALUES (NULL, 'seed', 'complexity', 'hard', 'fr', 'php', 'Le coût du décalage', 'Quelle est la complexité de `process` ?', 'function process(array $queue): int {
    // $queue has n integers
    $sum = 0;
    while (count($queue) > 0) {
        $x = array_shift($queue);     // take the first element
        $sum += $x;
    }
    return $sum;
}', '["O(n²) : array_shift réindexe tout le tableau à chaque fois", "O(n) : count() et array_shift sont en O(1)", "O(n log n)", "O(1)"]', 'A', 'Après array_shift, le premier élément a de nouveau la clé 0. Qu''a dû faire PHP aux autres ?', 'array_shift retire le premier élément et renumérote toutes les clés entières restantes, en O(n) à chaque fois : n + (n-1) + … = O(n²). count() est en O(1). Utilise un indice, array_reverse + array_pop, ou SplQueue pour O(n).', 'arrays', NULL, NULL, NULL, 'active', 'seed', 1791475200);
INSERT INTO challenges (guild_id, source, kind, difficulty, lang, code_lang, title, question, code, choices, answer, hint, explanation, topic, test_set, time_limit, solution, status, created_by, created_at) VALUES (NULL, 'seed', 'complexity', 'hard', 'en', 'php', 'Memoized grid', 'What is the time complexity of `paths($r, $c)` (first call, empty memo)?', 'function paths(int $r, int $c, array &$memo = []): int {
    // number of paths in a grid, moving right or down
    if ($r === 0 || $c === 0) return 1;
    $key = "$r,$c";
    if (isset($memo[$key])) return $memo[$key];
    return $memo[$key] = paths($r - 1, $c, $memo) + paths($r, $c - 1, $memo);
}', '["O(2^(r+c))", "O(r + c)", "O(r·c)", "O((r+c)²)"]', 'C', 'How many different (r, c) pairs can be stored in $memo? What does each cost?', 'Each state (i, j) with 0 ≤ i ≤ r and 0 ≤ j ≤ c is computed once, with O(1) work besides the two calls: O(r·c). Without the memo (or without `&`, which would copy the array) it would explode to about 2^(r+c).', 'recursion', NULL, NULL, NULL, 'active', 'seed', 1791475200);
INSERT INTO challenges (guild_id, source, kind, difficulty, lang, code_lang, title, question, code, choices, answer, hint, explanation, topic, test_set, time_limit, solution, status, created_by, created_at) VALUES (NULL, 'seed', 'complexity', 'hard', 'fr', 'php', 'Grille mémoïsée', 'Quelle est la complexité de `paths($r, $c)` (premier appel, memo vide) ?', 'function paths(int $r, int $c, array &$memo = []): int {
    // number of paths in a grid, moving right or down
    if ($r === 0 || $c === 0) return 1;
    $key = "$r,$c";
    if (isset($memo[$key])) return $memo[$key];
    return $memo[$key] = paths($r - 1, $c, $memo) + paths($r, $c - 1, $memo);
}', '["O(2^(r+c))", "O(r + c)", "O(r·c)", "O((r+c)²)"]', 'C', 'Combien de paires (r, c) différentes peuvent être stockées dans $memo ? Combien coûte chacune ?', 'Chaque état (i, j) avec 0 ≤ i ≤ r et 0 ≤ j ≤ c est calculé une fois, avec un travail O(1) en plus des deux appels : O(r·c). Sans memo (ou sans `&`, qui copierait le tableau), on exploserait vers 2^(r+c).', 'recursion', NULL, NULL, NULL, 'active', 'seed', 1791475200);
INSERT INTO challenges (guild_id, source, kind, difficulty, lang, code_lang, title, question, code, choices, answer, hint, explanation, topic, test_set, time_limit, solution, status, created_by, created_at) VALUES (NULL, 'seed', 'bug', 'hard', 'en', 'php', 'Memo that forgets', '`fib(30)` gives the right answer but takes millions of calls. Why doesn''t the memo help?', 'function fib(int $n, array $memo = []): int {
    if ($n <= 1) return $n;
    if (isset($memo[$n])) return $memo[$n];
    $memo[$n] = fib($n - 1, $memo) + fib($n - 2, $memo);
    return $memo[$n];
}
echo fib(30);', '["isset() doesn''t work with integer keys", "Arrays are passed by value: each call fills its own copy of $memo and the results never reach the caller, so the recursion stays exponential. Use `array &$memo` or a static array", "The return type should be `float`", "The base case must be `$n === 0`"]', 'B', 'When fib($n - 1, $memo) writes into $memo, does the caller''s $memo change?', 'Without &, PHP copies the array for each call (copy-on-write), so values computed in fib(n-1) are lost before fib(n-2) runs. The memo never hits and the complexity stays O(φⁿ). Pass it by reference (`array &$memo = []`) or use `static $memo = []`.', 'recursion', NULL, NULL, NULL, 'active', 'seed', 1791475200);
INSERT INTO challenges (guild_id, source, kind, difficulty, lang, code_lang, title, question, code, choices, answer, hint, explanation, topic, test_set, time_limit, solution, status, created_by, created_at) VALUES (NULL, 'seed', 'bug', 'hard', 'fr', 'php', 'Le memo qui oublie', '`fib(30)` donne le bon résultat mais fait des millions d''appels. Pourquoi le memo n''aide-t-il pas ?', 'function fib(int $n, array $memo = []): int {
    if ($n <= 1) return $n;
    if (isset($memo[$n])) return $memo[$n];
    $memo[$n] = fib($n - 1, $memo) + fib($n - 2, $memo);
    return $memo[$n];
}
echo fib(30);', '["isset() ne marche pas avec des clés entières", "Les tableaux sont passés par valeur : chaque appel remplit sa propre copie de $memo et les résultats ne remontent jamais, la récursion reste exponentielle. Utilise `array &$memo` ou un tableau static", "Le type de retour devrait être `float`", "Le cas de base doit être `$n === 0`"]', 'B', 'Quand fib($n - 1, $memo) écrit dans $memo, le $memo de l''appelant change-t-il ?', 'Sans &, PHP copie le tableau à chaque appel (copie à l''écriture) : les valeurs calculées dans fib(n-1) sont perdues avant fib(n-2). Le memo ne sert jamais et la complexité reste O(φⁿ). Passe-le par référence (`array &$memo = []`) ou utilise `static $memo = []`.', 'recursion', NULL, NULL, NULL, 'active', 'seed', 1791475200);
INSERT INTO challenges (guild_id, source, kind, difficulty, lang, code_lang, title, question, code, choices, answer, hint, explanation, topic, test_set, time_limit, solution, status, created_by, created_at) VALUES (NULL, 'seed', 'bug', 'hard', 'en', 'php', 'Due date', 'The teacher wanted the start date to stay 2026-01-31 and the due date one month later. It prints `2026-03-03 2026-03-03`. What are the TWO problems?', '$start = new DateTime("2026-01-31");
$due = $start;
$due->modify("+1 month");
echo $start->format("Y-m-d"), " ", $due->format("Y-m-d");', '["DateTime can''t parse ISO dates, and modify() needs seconds", "format() changes the date, and \"+1 month\" means 30 days", "`$due = $start` copies the object handle, so both variables are the same object; and \"+1 month\" on Jan 31 overflows Feb 31 to March 3. Use `DateTimeImmutable` (or clone) and \"last day of next month\" when needed", "Months start at 0 in PHP"]', 'C', 'Objects are handles. And what is February 31?', 'Assigning an object doesn''t copy it: modifying $due modifies $start. "+1 month" adds one to the month (Feb 31), which overflows into March 3 (2026 isn''t a leap year). DateTimeImmutable::modify returns a new object, and "last day of next month" avoids the overflow.', 'dates', NULL, NULL, NULL, 'active', 'seed', 1791475200);
INSERT INTO challenges (guild_id, source, kind, difficulty, lang, code_lang, title, question, code, choices, answer, hint, explanation, topic, test_set, time_limit, solution, status, created_by, created_at) VALUES (NULL, 'seed', 'bug', 'hard', 'fr', 'php', 'Date d''échéance', 'L''enseignant voulait garder le début au 2026-01-31 et l''échéance un mois plus tard. Ça affiche `2026-03-03 2026-03-03`. Quels sont les DEUX problèmes ?', '$start = new DateTime("2026-01-31");
$due = $start;
$due->modify("+1 month");
echo $start->format("Y-m-d"), " ", $due->format("Y-m-d");', '["DateTime ne lit pas les dates ISO, et modify() veut des secondes", "format() modifie la date, et « +1 month » veut dire 30 jours", "`$due = $start` copie la poignée de l''objet : les deux variables sont le même objet ; et « +1 month » le 31 janvier déborde du 31 février au 3 mars. Utilise `DateTimeImmutable` (ou clone) et « last day of next month » si besoin", "Les mois commencent à 0 en PHP"]', 'C', 'Les objets sont des poignées. Et qu''est-ce que le 31 février ?', 'Affecter un objet ne le copie pas : modifier $due modifie $start. « +1 month » ajoute un au mois (31 février), qui déborde au 3 mars (2026 n''est pas bissextile). DateTimeImmutable::modify renvoie un nouvel objet, et « last day of next month » évite le débordement.', 'dates', NULL, NULL, NULL, 'active', 'seed', 1791475200);
INSERT INTO challenges (guild_id, source, kind, difficulty, lang, code_lang, title, question, code, choices, answer, hint, explanation, topic, test_set, time_limit, solution, status, created_by, created_at) VALUES (NULL, 'seed', 'bug', 'hard', 'en', 'php', 'Read a file', 'What is the serious problem with this code?', '// page.php?file=report.txt
$file = $_GET["file"];
echo file_get_contents(__DIR__ . "/uploads/" . $file);', '["Path traversal: `?file=../../config.php` reads any file on the server. Use `basename()` and a whitelist, and check the resolved `realpath` stays inside uploads/", "file_get_contents can''t read .txt files", "`__DIR__` is the root of the server", "$_GET values are always integers"]', 'A', 'What if the user sends `../` in the parameter?', 'The user controls part of the path, so `../` escapes the uploads folder (database passwords, source code…). Keep only the file name (basename), check it against the list of allowed files, and verify that realpath() is still inside the uploads directory.', 'security', NULL, NULL, NULL, 'active', 'seed', 1791475200);
INSERT INTO challenges (guild_id, source, kind, difficulty, lang, code_lang, title, question, code, choices, answer, hint, explanation, topic, test_set, time_limit, solution, status, created_by, created_at) VALUES (NULL, 'seed', 'bug', 'hard', 'fr', 'php', 'Lire un fichier', 'Quel est le problème grave de ce code ?', '// page.php?file=report.txt
$file = $_GET["file"];
echo file_get_contents(__DIR__ . "/uploads/" . $file);', '["Traversée de chemin : `?file=../../config.php` lit n''importe quel fichier du serveur. Utilise `basename()` et une liste blanche, et vérifie que le `realpath` reste dans uploads/", "file_get_contents ne lit pas les .txt", "`__DIR__` est la racine du serveur", "Les valeurs de $_GET sont toujours des entiers"]', 'A', 'Et si l''utilisateur envoie `../` dans le paramètre ?', 'L''utilisateur contrôle une partie du chemin : `../` sort du dossier uploads (mots de passe de la base, code source…). Ne garde que le nom du fichier (basename), compare-le à la liste des fichiers autorisés, et vérifie que realpath() reste dans le dossier uploads.', 'security', NULL, NULL, NULL, 'active', 'seed', 1791475200);
INSERT INTO challenges (guild_id, source, kind, difficulty, lang, code_lang, title, question, code, choices, answer, hint, explanation, topic, test_set, time_limit, solution, status, created_by, created_at) VALUES (NULL, 'seed', 'write', 'easy', 'en', NULL, 'Runner-up', 'Given **n** integers, print the **second largest distinct** value. If all values are equal, print `-1`.

**Input**
The first line contains n. The second line contains n integers.

**Output**
One integer.

**Constraints**
1 ≤ n ≤ 200 000 · |aᵢ| ≤ 10⁹', NULL, NULL, NULL, 'Duplicates of the maximum don''t count as the second largest. A set or two variables will do.', NULL, 'arrays', 'second-largest', 2.0, 'import sys
data = sys.stdin.read().split()
n = int(data[0])
vals = sorted(set(map(int, data[1:1 + n])), reverse=True)
print(vals[1] if len(vals) > 1 else -1)
', 'active', 'seed', 1791475200);
INSERT INTO challenges (guild_id, source, kind, difficulty, lang, code_lang, title, question, code, choices, answer, hint, explanation, topic, test_set, time_limit, solution, status, created_by, created_at) VALUES (NULL, 'seed', 'write', 'easy', 'fr', NULL, 'Dauphin', 'On te donne **n** entiers. Affiche la **deuxième plus grande valeur distincte**. Si toutes les valeurs sont égales, affiche `-1`.

**Entrée**
La première ligne contient n. La deuxième contient n entiers.

**Sortie**
Un entier.

**Contraintes**
1 ≤ n ≤ 200 000 · |aᵢ| ≤ 10⁹', NULL, NULL, NULL, 'Les doublons du maximum ne comptent pas. Un ensemble ou deux variables suffisent.', NULL, 'arrays', 'second-largest', 2.0, 'import sys
data = sys.stdin.read().split()
n = int(data[0])
vals = sorted(set(map(int, data[1:1 + n])), reverse=True)
print(vals[1] if len(vals) > 1 else -1)
', 'active', 'seed', 1791475200);
INSERT INTO challenges (guild_id, source, kind, difficulty, lang, code_lang, title, question, code, choices, answer, hint, explanation, topic, test_set, time_limit, solution, status, created_by, created_at) VALUES (NULL, 'seed', 'write', 'easy', 'en', NULL, 'Squeeze it', 'Compress a string with **run-length encoding**: replace every maximal block of identical letters by the letter followed by the length of the block (always written, even when it is 1).

Example: `aaabccdddd` → `a3b1c2d4`

**Input**
One line with a string s of lowercase letters.

**Output**
The encoded string.

**Constraints**
1 ≤ |s| ≤ 10 000', NULL, NULL, NULL, 'Walk through the string and count how long the current letter repeats before it changes.', NULL, 'strings', 'run-length', 2.0, 's = input().strip()
out = []
i = 0
while i < len(s):
    j = i
    while j < len(s) and s[j] == s[i]:
        j += 1
    out.append(s[i] + str(j - i))
    i = j
print("".join(out))
', 'active', 'seed', 1791475200);
INSERT INTO challenges (guild_id, source, kind, difficulty, lang, code_lang, title, question, code, choices, answer, hint, explanation, topic, test_set, time_limit, solution, status, created_by, created_at) VALUES (NULL, 'seed', 'write', 'easy', 'fr', NULL, 'Compresse-moi', 'Compresse une chaîne avec le **codage par plages** : remplace chaque bloc maximal de lettres identiques par la lettre suivie de la longueur du bloc (toujours écrite, même quand elle vaut 1).

Exemple : `aaabccdddd` → `a3b1c2d4`

**Entrée**
Une ligne avec une chaîne s de lettres minuscules.

**Sortie**
La chaîne encodée.

**Contraintes**
1 ≤ |s| ≤ 10 000', NULL, NULL, NULL, 'Parcours la chaîne et compte combien de fois la lettre courante se répète avant de changer.', NULL, 'strings', 'run-length', 2.0, 's = input().strip()
out = []
i = 0
while i < len(s):
    j = i
    while j < len(s) and s[j] == s[i]:
        j += 1
    out.append(s[i] + str(j - i))
    i = j
print("".join(out))
', 'active', 'seed', 1791475200);
INSERT INTO challenges (guild_id, source, kind, difficulty, lang, code_lang, title, question, code, choices, answer, hint, explanation, topic, test_set, time_limit, solution, status, created_by, created_at) VALUES (NULL, 'seed', 'write', 'easy', 'en', NULL, 'Bracket police', 'For each string made of `()[]{}`, print `YES` if it is **balanced** (every bracket is closed by the matching bracket, in the right order) and `NO` otherwise.

**Input**
The first line contains q. Each of the next q lines contains one non-empty string.

**Output**
q lines, `YES` or `NO`.

**Constraints**
1 ≤ q ≤ 1 000 · each string has at most 2 000 characters', NULL, NULL, NULL, 'Push opening brackets on a stack. A closing bracket must match the top of the stack. What must the stack look like at the end?', NULL, 'stacks', 'balanced-brackets', 2.0, 'import sys
lines = sys.stdin.read().split()
q = int(lines[0])
pair = {")": "(", "]": "[", "}": "{"}
out = []
for s in lines[1:1 + q]:
    st = []
    ok = True
    for ch in s:
        if ch in "([{":
            st.append(ch)
        elif not st or st.pop() != pair[ch]:
            ok = False
            break
    out.append("YES" if ok and not st else "NO")
print("\n".join(out))
', 'active', 'seed', 1791475200);
INSERT INTO challenges (guild_id, source, kind, difficulty, lang, code_lang, title, question, code, choices, answer, hint, explanation, topic, test_set, time_limit, solution, status, created_by, created_at) VALUES (NULL, 'seed', 'write', 'easy', 'fr', NULL, 'Police des parenthèses', 'Pour chaque chaîne composée de `()[]{}`, affiche `YES` si elle est **bien parenthésée** (chaque symbole ouvrant est fermé par le bon symbole, dans le bon ordre) et `NO` sinon.

**Entrée**
La première ligne contient q. Chacune des q lignes suivantes contient une chaîne non vide.

**Sortie**
q lignes, `YES` ou `NO`.

**Contraintes**
1 ≤ q ≤ 1 000 · chaque chaîne a au plus 2 000 caractères', NULL, NULL, NULL, 'Empile les symboles ouvrants. Un symbole fermant doit correspondre au sommet de la pile. À quoi doit ressembler la pile à la fin ?', NULL, 'stacks', 'balanced-brackets', 2.0, 'import sys
lines = sys.stdin.read().split()
q = int(lines[0])
pair = {")": "(", "]": "[", "}": "{"}
out = []
for s in lines[1:1 + q]:
    st = []
    ok = True
    for ch in s:
        if ch in "([{":
            st.append(ch)
        elif not st or st.pop() != pair[ch]:
            ok = False
            break
    out.append("YES" if ok and not st else "NO")
print("\n".join(out))
', 'active', 'seed', 1791475200);
INSERT INTO challenges (guild_id, source, kind, difficulty, lang, code_lang, title, question, code, choices, answer, hint, explanation, topic, test_set, time_limit, solution, status, created_by, created_at) VALUES (NULL, 'seed', 'write', 'easy', 'en', NULL, 'Plateau', 'A **plateau** is a block of consecutive equal values. Print the length of the longest plateau and its value. If several plateaus have the maximum length, print the one with the **smallest value**.

**Input**
The first line contains n. The second line contains n integers.

**Output**
Two integers: the length and the value.

**Constraints**
1 ≤ n ≤ 200 000 · |aᵢ| ≤ 10⁹', NULL, NULL, NULL, 'Keep the length of the current run; when the value changes, compare it with the best so far. Don''t forget the last run.', NULL, 'arrays', 'longest-plateau', 2.0, 'import sys
data = sys.stdin.read().split()
n = int(data[0])
a = list(map(int, data[1:1 + n]))
best_len, best_val = 0, None
i = 0
while i < n:
    j = i
    while j < n and a[j] == a[i]:
        j += 1
    L = j - i
    if L > best_len or (L == best_len and a[i] < best_val):
        best_len, best_val = L, a[i]
    i = j
print(best_len, best_val)
', 'active', 'seed', 1791475200);
INSERT INTO challenges (guild_id, source, kind, difficulty, lang, code_lang, title, question, code, choices, answer, hint, explanation, topic, test_set, time_limit, solution, status, created_by, created_at) VALUES (NULL, 'seed', 'write', 'easy', 'fr', NULL, 'Plateau', 'Un **plateau** est un bloc de valeurs consécutives égales. Affiche la longueur du plus long plateau et sa valeur. Si plusieurs plateaux ont la longueur maximale, affiche celui dont la **valeur est la plus petite**.

**Entrée**
La première ligne contient n. La deuxième contient n entiers.

**Sortie**
Deux entiers : la longueur et la valeur.

**Contraintes**
1 ≤ n ≤ 200 000 · |aᵢ| ≤ 10⁹', NULL, NULL, NULL, 'Garde la longueur du bloc courant ; quand la valeur change, compare-la au meilleur. N''oublie pas le dernier bloc.', NULL, 'arrays', 'longest-plateau', 2.0, 'import sys
data = sys.stdin.read().split()
n = int(data[0])
a = list(map(int, data[1:1 + n]))
best_len, best_val = 0, None
i = 0
while i < n:
    j = i
    while j < n and a[j] == a[i]:
        j += 1
    L = j - i
    if L > best_len or (L == best_len and a[i] < best_val):
        best_len, best_val = L, a[i]
    i = j
