INSERT INTO challenges (guild_id, source, kind, difficulty, lang, code_lang, title, question, code, choices, answer, hint, explanation, topic, test_set, time_limit, solution, status, created_by, created_at) VALUES (NULL, 'seed', 'write', 'medium', 'en', NULL, 'Maze runner', 'A maze has `.` (free), `#` (wall), one `S` (start) and one `E` (exit). You move up, down, left or right to a free cell (S and E are free). Print the **minimum number of moves** from S to E, or `-1` if it''s impossible.

**Input**
The first line contains R and C. Then R lines of C characters.

**Output**
One integer.

**Constraints**
1 ≤ R, C ≤ 500', NULL, NULL, NULL, 'Breadth-first search from S: the first time you reach a cell is with its shortest distance. Mark cells as visited when you add them to the queue.', NULL, 'BFS', 'grid-escape', 2.0, 'import sys
from collections import deque
data = sys.stdin.read().split()
R, C = int(data[0]), int(data[1])
g = data[2:2 + R]
for i in range(R):
    j = g[i].find("S")
    if j >= 0:
        s = (i, j)
    j = g[i].find("E")
    if j >= 0:
        e = (i, j)
dist = [[-1] * C for _ in range(R)]
dist[s[0]][s[1]] = 0
q = deque([s])
while q:
    r, c = q.popleft()
    if (r, c) == e:
        break
    d = dist[r][c] + 1
    for nr, nc in ((r + 1, c), (r - 1, c), (r, c + 1), (r, c - 1)):
        if 0 <= nr < R and 0 <= nc < C and dist[nr][nc] < 0 and g[nr][nc] != "#":
            dist[nr][nc] = d
            q.append((nr, nc))
print(dist[e[0]][e[1]])
', 'active', 'seed', 1791475200);
