INSERT INTO challenges (guild_id, source, kind, difficulty, lang, code_lang, title, question, code, choices, answer, hint, explanation, topic, test_set, time_limit, solution, status, created_by, created_at) VALUES (NULL, 'seed', 'write', 'medium', 'en', NULL, 'Making change', 'You have n coin values (unlimited coins of each). In how many ways can you pay exactly **x**? The order of the coins doesn''t matter: 2+3 and 3+2 are the same way. Print the answer **modulo 1 000 000 007**.

**Input**
The first line contains n and x. The second line contains n distinct coin values.

**Output**
One integer.

**Constraints**
1 ≤ n ≤ 50 · 1 ≤ x ≤ 20 000 · 1 ≤ cᵢ ≤ x', NULL, NULL, NULL, 'ways[v] = number of ways to make v. Loop over coins in the OUTER loop and over amounts in the inner loop, so each combination is counted once.', NULL, 'dynamic programming', 'coin-combinations', 2.0, 'n, x = map(int, input().split())
coins = list(map(int, input().split()))
MOD = 10**9 + 7
ways = [0] * (x + 1)
ways[0] = 1
for c in coins:
    for v in range(c, x + 1):
        ways[v] = (ways[v] + ways[v - c]) % MOD
