INSERT INTO challenges (guild_id, source, kind, difficulty, lang, code_lang, title, question, code, choices, answer, hint, explanation, topic, test_set, time_limit, solution, status, created_by, created_at) VALUES (NULL, 'seed', 'write', 'hard', 'en', NULL, 'Always climbing', 'Print the length of the **longest strictly increasing subsequence** of the array (a subsequence keeps the order but can skip elements).

**Input**
The first line contains n. The second line contains n integers.

**Output**
One integer.

**Constraints**
1 ≤ n ≤ 200 000 · |aᵢ| ≤ 10⁹

⚠️ The classic O(n²) DP is far too slow for the big tests. You need O(n log n).', NULL, NULL, NULL, 'Keep tails[k] = the smallest possible last value of an increasing subsequence of length k+1. tails stays sorted, so each new value is placed with a binary search.', NULL, 'binary search · DP', 'lis', 3.0, 'import sys
from bisect import bisect_left
data = sys.stdin.read().split()
n = int(data[0])
tails = []
for x in map(int, data[1:1 + n]):
    i = bisect_left(tails, x)
    if i == len(tails):
        tails.append(x)
    else:
        tails[i] = x
print(len(tails))
