INSERT INTO challenges (guild_id, source, kind, difficulty, lang, code_lang, title, question, code, choices, answer, hint, explanation, topic, test_set, time_limit, solution, status, created_by, created_at) VALUES (NULL, 'seed', 'write', 'hard', 'fr', NULL, 'Toujours plus haut', 'Affiche la longueur de la **plus longue sous-suite strictement croissante** du tableau (une sous-suite garde l''ordre mais peut sauter des éléments).

**Entrée**
La première ligne contient n. La deuxième contient n entiers.

**Sortie**
Un entier.

**Contraintes**
1 ≤ n ≤ 200 000 · |aᵢ| ≤ 10⁹

⚠️ La programmation dynamique classique en O(n²) est bien trop lente pour les gros tests. Il faut du O(n log n).', NULL, NULL, NULL, 'Garde tails[k] = la plus petite dernière valeur possible d''une sous-suite croissante de longueur k+1. tails reste trié : chaque nouvelle valeur se place par dichotomie.', NULL, 'binary search · DP', 'lis', 3.0, 'import sys
from bisect import bisect_left
data = sys.stdin.read().split()
