INSERT INTO challenges (guild_id, source, kind, difficulty, lang, code_lang, title, question, code, choices, answer, hint, explanation, topic, test_set, time_limit, solution, status, created_by, created_at) VALUES (NULL, 'seed', 'write', 'hard', 'en', NULL, 'Out of order', 'An **inversion** is a pair of positions i < j with aᵢ > aⱼ. Print the number of inversions.

**Input**
The first line contains n. The second line contains n integers.

**Output**
One integer (it can be larger than 2³¹).

**Constraints**
1 ≤ n ≤ 200 000 · 1 ≤ aᵢ ≤ 10⁹

⚠️ O(n²) is far too slow for the big tests.', NULL, NULL, NULL, 'Merge sort: when you take an element from the right half before elements of the left half, each remaining left element forms an inversion with it. A Fenwick tree works too.', NULL, 'divide and conquer', 'inversions', 3.0, 'import sys
def count(a):
    n = len(a)
    if n < 2:
        return a, 0
    mid = n // 2
    left, x = count(a[:mid])
    right, y = count(a[mid:])
    inv = x + y
    merged = []
    i = j = 0
    while i < len(left) and j < len(right):
        if left[i] <= right[j]:
            merged.append(left[i]); i += 1
        else:
            merged.append(right[j]); j += 1
            inv += len(left) - i
    merged.extend(left[i:]); merged.extend(right[j:])
    return merged, inv
data = sys.stdin.read().split()
n = int(data[0])
print(count(list(map(int, data[1:1 + n])))[1])
', 'active', 'seed', 1791475200);
INSERT INTO challenges (guild_id, source, kind, difficulty, lang, code_lang, title, question, code, choices, answer, hint, explanation, topic, test_set, time_limit, solution, status, created_by, created_at) VALUES (NULL, 'seed', 'write', 'hard', 'fr', NULL, 'Dans le désordre', 'Une **inversion** est une paire de positions i < j avec aᵢ > aⱼ. Affiche le nombre d''inversions.

**Entrée**
La première ligne contient n. La deuxième contient n entiers.

**Sortie**
Un entier (il peut dépasser 2³¹).

**Contraintes**
1 ≤ n ≤ 200 000 · 1 ≤ aᵢ ≤ 10⁹

⚠️ Une solution en O(n²) est bien trop lente pour les gros tests.', NULL, NULL, NULL, 'Tri fusion : quand on prend un élément de la moitié droite avant des éléments de la moitié gauche, chaque élément gauche restant forme une inversion avec lui. Un arbre de Fenwick marche aussi.', NULL, 'divide and conquer', 'inversions', 3.0, 'import sys
def count(a):
    n = len(a)
    if n < 2:
        return a, 0
    mid = n // 2
    left, x = count(a[:mid])
    right, y = count(a[mid:])
    inv = x + y
    merged = []
    i = j = 0
    while i < len(left) and j < len(right):
        if left[i] <= right[j]:
            merged.append(left[i]); i += 1
        else:
            merged.append(right[j]); j += 1
            inv += len(left) - i
    merged.extend(left[i:]); merged.extend(right[j:])
    return merged, inv
data = sys.stdin.read().split()
n = int(data[0])
print(count(list(map(int, data[1:1 + n])))[1])
', 'active', 'seed', 1791475200);
INSERT INTO challenges (guild_id, source, kind, difficulty, lang, code_lang, title, question, code, choices, answer, hint, explanation, topic, test_set, time_limit, solution, status, created_by, created_at) VALUES (NULL, 'seed', 'write', 'hard', 'en', NULL, 'Cheapest route', 'A country has n cities and m two-way roads, each with a toll. Print the **minimum total toll** to travel from city 1 to city n, or `-1` if city n can''t be reached.

**Input**
The first line contains n and m. Each of the next m lines contains u, v, w: a road between u and v with toll w.

**Output**
One integer.

**Constraints**
2 ≤ n ≤ 100 000 · 1 ≤ m ≤ 200 000 · 1 ≤ w ≤ 10⁹ (several roads can join the same cities)', NULL, NULL, NULL, 'Dijkstra with a priority queue (heapq). Skip a popped entry if its distance is larger than the best known one.', NULL, 'Dijkstra', 'cheapest-route', 3.0, 'import sys, heapq
data = sys.stdin.buffer.read().split()
n, m = int(data[0]), int(data[1])
adj = [[] for _ in range(n + 1)]
p = 2
for _ in range(m):
    u, v, w = int(data[p]), int(data[p + 1]), int(data[p + 2])
    p += 3
    adj[u].append((v, w))
    adj[v].append((u, w))
INF = float("inf")
dist = [INF] * (n + 1)
dist[1] = 0
pq = [(0, 1)]
while pq:
    d, u = heapq.heappop(pq)
    if d > dist[u]:
        continue
    if u == n:
        break
    for v, w in adj[u]:
        nd = d + w
        if nd < dist[v]:
            dist[v] = nd
            heapq.heappush(pq, (nd, v))
print(dist[n] if dist[n] < INF else -1)
', 'active', 'seed', 1791475200);
