INSERT INTO challenges (guild_id, source, kind, difficulty, lang, code_lang, title, question, code, choices, answer, hint, explanation, topic, test_set, time_limit, solution, status, created_by, created_at) VALUES (NULL, 'seed', 'write', 'hard', 'en', NULL, 'Peak watch', 'For every window of k **consecutive** elements, take its maximum. Print the **sum** of all these maximums (there are n - k + 1 windows).

**Input**
The first line contains n and k. The second line contains n integers.

**Output**
One integer.

**Constraints**
1 ≤ k ≤ n ≤ 200 000 · |aᵢ| ≤ 10⁹

⚠️ With k around n / 2, recomputing every maximum (O(n·k)) is far too slow.', NULL, NULL, NULL, 'A deque of indexes whose values are decreasing: the front is the window''s maximum. Pop smaller values from the back before pushing, and drop the front when it leaves the window.', NULL, 'monotonic deque', 'window-max-sum', 3.0, 'import sys
from collections import deque
data = sys.stdin.read().split()
n, k = int(data[0]), int(data[1])
a = list(map(int, data[2:2 + n]))
dq = deque()
total = 0
for i, x in enumerate(a):
    while dq and a[dq[-1]] <= x:
        dq.pop()
    dq.append(i)
    if dq[0] <= i - k:
        dq.popleft()
    if i >= k - 1:
        total += a[dq[0]]
print(total)
', 'active', 'seed', 1791475200);
