INSERT INTO challenges (guild_id, source, kind, difficulty, lang, code_lang, title, question, code, choices, answer, hint, explanation, topic, test_set, time_limit, solution, status, created_by, created_at) VALUES (NULL, 'seed', 'write', 'hard', 'en', NULL, 'Biggest poster', 'n buildings stand side by side, each 1 meter wide, with heights h₁ … hₙ. Print the **largest area** of a rectangle (aligned with the ground) that fits entirely inside the skyline.

**Input**
The first line contains n. The second line contains n heights.

**Output**
One integer.

**Constraints**
1 ≤ n ≤ 200 000 · 0 ≤ hᵢ ≤ 10⁹

⚠️ O(n²) is far too slow for the big tests.', NULL, NULL, NULL, 'For each bar, find how far it can stretch left and right before meeting a lower bar. A stack of increasing heights gives both limits in one pass.', NULL, 'monotonic stack', 'histogram', 3.0, 'import sys
data = sys.stdin.read().split()
n = int(data[0])
h = list(map(int, data[1:1 + n])) + [0]
st = []
best = 0
for i, x in enumerate(h):
    start = i
    while st and st[-1][1] >= x:
        j, y = st.pop()
        best = max(best, y * (i - j))
        start = j
    st.append((start, x))
print(best)
', 'active', 'seed', 1791475200);
INSERT INTO challenges (guild_id, source, kind, difficulty, lang, code_lang, title, question, code, choices, answer, hint, explanation, topic, test_set, time_limit, solution, status, created_by, created_at) VALUES (NULL, 'seed', 'write', 'hard', 'fr', NULL, 'La plus grande affiche', 'n immeubles sont côte à côte, chacun large d''1 mètre, de hauteurs h₁ … hₙ. Affiche la **plus grande aire** d''un rectangle (aligné avec le sol) qui tient entièrement dans la silhouette.

