INSERT INTO challenges (guild_id, source, kind, difficulty, lang, code_lang, title, question, code, choices, answer, hint, explanation, topic, test_set, time_limit, solution, status, created_by, created_at) VALUES (NULL, 'seed', 'write', 'hard', 'en', NULL, 'Typo fixer', 'Turn string s into string t using the fewest operations. One operation inserts one character, deletes one character, or replaces one character by another. Print the minimum number of operations.

**Input**
Two lines: s and t (lowercase letters).

**Output**
One integer.

**Constraints**
1 ≤ |s|, |t| ≤ 1 000', NULL, NULL, NULL, 'dp[i][j] = cost to turn the first i letters of s into the first j letters of t. Each cell depends on its left, top and top-left neighbours. Keeping two rows is enough.', NULL, 'dynamic programming', 'edit-distance', 3.0, 's = input().strip()
t = input().strip()
prev = list(range(len(t) + 1))
for i in range(1, len(s) + 1):
    cur = [i] + [0] * len(t)
    si = s[i - 1]
    for j in range(1, len(t) + 1):
        if si == t[j - 1]:
            cur[j] = prev[j - 1]
        else:
            cur[j] = 1 + min(prev[j], cur[j - 1], prev[j - 1])
    prev = cur
print(prev[len(t)])
', 'active', 'seed', 1791475200);
